    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]
    # Draw bounding-box frame and complete marked horizontal strokes (3+ points).
    for c in range(c0, c1 + 1):
        if grid[r0][c] == bg: out[r0][c] = 2
        if grid[r1][c] == bg: out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == bg: out[r][c0] = 2
        if grid[r][c1] == bg: out[r][c1] = 2
    for r in range(r0 + 1, r1):
        cs = [c for c in range(c0, c1 + 1) if grid[r][c] == ink]
        if len(cs) >= 3:
            for c in range(min(cs), max(cs) + 1):
